import { useState } from 'react';
import { stores, products, WHATSAPP_NUMBER, stockInfo } from './data';
import type { Product } from './data';

type Props = {
  product: Product;
    isFav: boolean;
      onToggleFav: () => void;
        onBack: () => void;
          onOpenStore: (storeId: number) => void;
            onOpenProduct?: (id: number) => void;
            };

            function ProductDetail({ product: p, isFav, onToggleFav, onBack, onOpenStore, onOpenProduct }: Props) {
              const [size, setSize] = useState("");
                const [color, setColor] = useState("");
                  const [qty, setQty] = useState(1);

                    const st = stores.find((s) => s.id === p.storeId)!;
                      const sk = stockInfo(p.stock);
                        const pct = p.oldPrice > p.price ? Math.round(((p.oldPrice - p.price) / p.oldPrice) * 100) : 0;
                          const canOrder = p.stock > 0 && size !== "" && color !== "";
                            const link =
                                "https://wa.me/" + WHATSAPP_NUMBER + "?text=" +
                                    encodeURIComponent(
                                          "مرحباً، أريد طلب: " + p.name + " من " + st.name +
                                                " | المقاس: " + size + " | اللون: " + color +
                                                      " | الكمية: " + qty + " | السعر: " + p.price * qty + " جنيه"
                                                          );

                                                            const sameCat = products.filter((x) => x.id !== p.id && x.category === p.category);
                                                              const similar = sameCat.length > 0
                                                                  ? sameCat
                                                                      : products.filter((x) => x.id !== p.id && x.storeId === p.storeId);
                                                                        const similarTitle = sameCat.length > 0 ? "منتجات مشابهة" : "المزيد من " + st.name;

                                                                          function openOther(id: number) {
                                                                              if (onOpenProduct) {
                                                                                    onOpenProduct(id);
                                                                                          window.scrollTo(0, 0);
                                                                                              }
                                                                                                }

                                                                                                  return (
                                                                                                      <div className="detail">
                                                                                                            <div className="top-bar">
                                                                                                                    <button className="round" onClick={onBack}>→</button>
                                                                                                                            <span className="t">تفاصيل المنتج</span>
                                                                                                                                    <button className="round" onClick={onToggleFav}>{isFav ? "❤️" : "🤍"}</button>
                                                                                                                                          </div>

                                                                                                                                                <div className="gallery">{p.icon}<span className="counter">1 / 1</span></div>

                                                                                                                                                      <div className="sheet">
                                                                                                                                                              <h2>{p.name}</h2>
                                                                                                                                                                      <p className="price">
                                                                                                                                                                                <span>{p.price} ج.م</span>
                                                                                                                                                                                          {pct > 0 && <span className="old">{p.oldPrice} ج.م</span>}
                                                                                                                                                                                                    {pct > 0 && <span className="off">{pct}% -</span>}
                                                                                                                                                                                                            </p>
                                                                                                                                                                                                                    <p className="line">⭐ {p.rating} | <span className={sk.cls}>{sk.text}</span></p>
                                                                                                                                                                                                                            <p className="line">
                                                                                                                                                                                                                                      🏪 <span className="link" onClick={() => onOpenStore(st.id)}>{st.name}</span>{" "}
                                                                                                                                                                                                                                                {st.verified && <span className="verified">✔ موثق</span>} | ⭐ {st.rating}
                                                                                                                                                                                                                                                        </p>
                                                                                                                                                                                                                                                                {pct > 0 && <p className="note">الخصم مقدم من المحل.</p>}

                                                                                                                                                                                                                                                                        <h4>المقاسات المتاحة</h4>
                                                                                                                                                                                                                                                                                <div className="chips">
                                                                                                                                                                                                                                                                                          {p.sizes.map((s) => {
                                                                                                                                                                                                                                                                                                      const out = p.unavailableSizes.includes(s);
                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                <button
                                                                                                                                                                                                                                                                                                                                                key={s}
                                                                                                                                                                                                                                                                                                                                                                disabled={out}
                                                                                                                                                                                                                                                                                                                                                                                className={"chip" + (size === s ? " on" : "") + (out ? " off-chip" : "")}
                                                                                                                                                                                                                                                                                                                                                                                                onClick={() => setSize(s)}
                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                              {s}
                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h4>الألوان المتاحة</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="chips">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {p.colors.map((c) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              key={c.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            title={c.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          className={"dot" + (color === c.name ? " on" : "")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style={{ background: c.hex }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onClick={() => setColor(c.name)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {color && <p className="note">اللون: {color}</p>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h4>الكمية (المتوفر: {p.stock})</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="qty">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button onClick={() => setQty(Math.max(1, qty - 1))}>−</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span>{qty}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button onClick={() => setQty(Math.min(Math.max(p.stock, 1), qty + 1))}>+</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h4>الوصف</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="desc">{p.desc}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h4>الخامة</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="desc">{p.material}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h4>طريقة العناية</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="desc">{p.care}</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h4>التوصيل</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="desc">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            رسوم التوصيل حسب ما يحدده المحل: {p.deliveryFee} ج.م (تقريبًا) | المدة: {p.deliveryDays}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {canOrder ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <a className="cta wa" href={link} target="_blank" rel="noreferrer">اطلب عبر واتساب</a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button className="cta disabled" disabled>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {p.stock === 0 ? "نفد مؤقتًا" : "اختر المقاس واللون أولًا"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {similar.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="sec-head"><h3>{similarTitle}</h3></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="cards">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {similar.map((x) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="card" key={x.id} onClick={() => openOther(x.id)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="img">{x.icon}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="info">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h2>{x.name}</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p className="price"><span>{x.price} ج.م</span></p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="shop">{stores.find((s) => s.id === x.storeId)?.name}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      export default ProductDetail;